import Foundation

// MARK: - Events

/// The kind of evidence an ``InspectorEvent`` represents.
///
/// Raw values are user-facing labels.
public enum EventKind: String, Sendable, CaseIterable {
    /// A user-authored message, or a notification presented in the user role.
    case user = "User message"
    /// An incoming chat-completion request.
    case request = "Inference request"
    /// Text generated by the model, as reported by the scheduler.
    case output = "Model output"
    /// A structured tool call reported in the agent's message history.
    case call = "Tool call"
    /// A tool result reported by the agent. This is not independent proof of execution.
    case result = "Tool result"
    /// Earlier assistant or other non-user context carried in a request's history.
    case context = "Carried context"
    /// A warning, error, or unattributed record worth surfacing.
    case diagnostic = "Diagnostic"

    /// The SF Symbols name used to represent this kind.
    public var symbol: String {
        switch self {
        case .user: "person.fill"
        case .request: "cpu"
        case .output: "text.bubble"
        case .call: "wrench.and.screwdriver"
        case .result: "arrow.turn.down.right"
        case .context: "text.alignleft"
        case .diagnostic: "exclamationmark.triangle"
        }
    }
}

/// The exact byte range of one source record, with the digest used to verify it on access.
public struct SourceRef: Sendable, Hashable {
    /// Byte offset of the record's first byte in the log file.
    public var offset: UInt64
    /// Length of the record in bytes, including its trailing newline.
    public var length: Int
    /// One-based line number of the record's first line.
    public var line: Int
    /// One-based line number of the record's last line.
    public var endLine: Int
    /// Lowercase hexadecimal SHA-256 digest of the record's bytes, compared before the bytes are displayed.
    public var digest: String = ""
}

/// Where an event's content lives: a source record, optionally narrowed to one message
/// or one tool call within a request's message history.
public struct Evidence: Sendable, Hashable {
    public var source: SourceRef
    /// Index into the request's `messages` array, when the event is a single message.
    public var messageIndex: Int? = nil
    /// Index into that message's `tool_calls` array, when the event is a single call.
    public var callIndex: Int? = nil
    /// Whether the source is a scheduler "generated text" record.
    public var generated = false
}

/// One item in a turn's timeline, with its explanatory note and source evidence.
public struct InspectorEvent: Identifiable, Sendable {
    /// Stable within a source generation. Derived from the source offset, so it can be
    /// persisted and restored when the same log is reopened.
    public var id: String
    public var kind: EventKind
    public var title: String
    /// A short, single-line preview of the content.
    public var summary: String
    /// The source record's timestamp, as written in the log.
    public var timestamp: String
    /// How this event was derived, and which parts are inferred.
    public var note: String
    public var evidence: Evidence
    /// The tool-call ID, for calls and results.
    public var toolID: String? = nil
    /// The ID of the matching call or result, when one is uniquely matched.
    public var linkedEvent: String? = nil
    /// The scheduler request UUID, when an association could be established.
    public var requestID: String? = nil
    /// For requests: why this request appears to have been made.
    public var continuation: RequestContinuation? = nil
    /// For requests: scheduler metrics and the comparison with a preceding request.
    public var metrics: RequestMetrics? = nil
    /// For requests and outputs: the associated server completion summary, if any.
    public var completion: InferenceCompletion? = nil
    /// For tool results: whether the agent reported the call as failed.
    public var reportsFailure = false

    /// The summary shown on timeline cards, with prompt tokens appended for requests.
    public var compactSummary: String {
        guard kind == .request else { return summary }
        let text = summary.replacingOccurrences(of: " tool definitions", with: " tools")
        guard let tokens = completion?.promptTokens ?? metrics?.promptTokens else { return text }
        return text + " · \(tokens.formatted()) prompt tokens"
    }

    /// Whether the event belongs in the "Errors & warnings" filter.
    public var isIssue: Bool { kind == .diagnostic || reportsFailure }
}

/// A user turn: one user message and the inference activity that followed it.
public struct InspectorTurn: Identifiable, Sendable {
    public var id: String
    public var title: String
    /// The inferred conversation this turn belongs to. Group `0` holds unattributed diagnostics.
    public var group: Int
    /// Timestamp of the record in which the turn was first observed.
    public var observed: String
    public var events: [InspectorEvent]

    /// The number of inference requests in this turn.
    public var requestCount: Int { events.filter { $0.kind == .request }.count }
    /// The number of structured tool calls in this turn.
    public var callCount: Int { events.filter { $0.kind == .call }.count }
}

// MARK: - Snapshots

/// An immutable view of an indexed log at one point in time.
///
/// Record bodies are not retained; they are read from disk on demand and verified against
/// each record's digest.
public struct LogSnapshot: Sendable {
    public var url: URL
    /// File size, in bytes, when the snapshot was taken.
    public var size: UInt64
    /// File-system inode, used to detect replacement and rotation.
    public var inode: UInt64
    public var modified: Date
    public var turns: [InspectorTurn]
    /// The number of framed records, including a trailing partial record.
    public var recordCount: Int
    /// Deduplicated, user-facing warnings gathered while indexing.
    public var warnings: [String]
    /// Identifies one continuous version of the source. A new value means the log was
    /// replaced, truncated, or rewritten, and earlier IDs no longer apply.
    public var generation: String = ""
    /// Whether the file ends with an incomplete line that is still being written.
    public var hasPartialRecord = false
    /// Every framed record, in source order.
    public var records = RecordList()
    /// The distinct logger names across ``records``, sorted.
    public var loggers: [String] = []

    public var requestCount: Int { turns.reduce(0) { total, turn in total + turn.requestCount } }
    public var callCount: Int { turns.reduce(0) { total, turn in total + turn.callCount } }
}

/// The content of one event or record in each of the Inspector's representations.
public struct EventDetail: Sendable {
    /// A concise interpretation for reading.
    public var readable: String
    /// The parsed content as pretty-printed JSON.
    public var structured: String
    /// The exact original source record.
    public var raw: String
    /// The parsed hierarchy behind the Structured outline, when requested and parseable.
    public var tree: StructuredValue? = nil
    /// The original server completion record, when one is associated.
    public var completionRaw: String? = nil
}

/// Errors reported while indexing or reading a log. Descriptions are user-facing.
public enum InspectorError: LocalizedError, Equatable {
    /// The chosen item is not a regular file.
    case notRegularFile
    /// The file changed while it was being indexed. Monitoring retries on its next pass.
    case sourceChangedWhileIndexing
    /// The file was replaced, truncated, or rewritten since the snapshot was taken.
    case sourceReplaced
    /// A record's bytes can no longer be read at its recorded position.
    case sourceUnavailable
    /// A record's bytes no longer match the digest taken when it was indexed.
    case recordChanged
    /// An incoming-request record has no decodable JSON object body.
    case unsupportedRequestBody
    /// A request body has no `messages`, or an empty list.
    case missingMessages
    /// A single record exceeded the safety limit. `indexedEvidenceAvailable` is `true` when
    /// an earlier snapshot of the same log remains usable.
    case recordTooLarge(indexedEvidenceAvailable: Bool)

    public var errorDescription: String? {
        switch self {
        case .notRegularFile: "Choose a regular log file."
        case .sourceChangedWhileIndexing: "The source changed while indexing. Monitoring will retry."
        case .sourceReplaced:
            "The source was replaced, truncated, or rewritten. Reopen the log before inspecting its evidence."
        case .sourceUnavailable: "Source content is no longer available. Reopen the log."
        case .recordChanged: "This source record has changed since the snapshot was opened. Reopen the log."
        case .unsupportedRequestBody: "Unsupported request body"
        case .missingMessages: "Missing messages"
        case .recordTooLarge(let available):
            available
                ? "Monitoring paused: a log record exceeds the 64 MiB safety limit. Previously indexed evidence remains available. The source log is unchanged; choose another log to continue."
                : "This log could not be indexed because a record exceeds the 64 MiB safety limit. No partial index was opened. The source log is unchanged; choose another log."
        }
    }
}

// MARK: - Requests

/// Presentation metadata derived from the exact message-prefix comparison, never parsed from diagnostic prose.
public struct RequestContinuation: Sendable {
    /// Why the request appears to have been made, worded as an inference.
    public var reason: String
    /// The number of messages in the request.
    public var totalMessages: Int
    /// The number of messages carried over from the matched predecessor, or `nil` when
    /// no unique predecessor was found.
    public var retainedMessages: Int?
    /// The reasoning behind the continuity decision.
    public var explanation: String? = nil

    public var messageDescription: String {
        guard let retainedMessages else { return "\(totalMessages) messages in context" }
        let added = totalMessages - retainedMessages
        return
            "\(added) new message\(added == 1 ? "" : "s") · \(retainedMessages) previous message\(retainedMessages == 1 ? "" : "s") retained"
    }
}

/// Non-destructive grouping of the existing observed sequence. Calls/results carried by a subsequent
/// request remain after the previous output; this is presentation order, not proof of execution timing.
public struct TimelineCycle: Identifiable, Sendable {
    public var id: String
    /// The one-based inference number, or `nil` for events before the turn's first request.
    public var number: Int?
    public var events: [InspectorEvent]
    public var completion: InferenceCompletion? = nil
}

public extension InspectorTurn {
    /// Groups the turn's events into inference cycles, each starting at a request.
    ///
    /// - Parameter showContext: Whether to keep ``EventKind/context`` events. Cycles left
    ///   empty by filtering are omitted.
    func timelineCycles(showContext: Bool) -> [TimelineCycle] {
        var cycles: [TimelineCycle] = []
        var number = 0
        for event in events {
            if event.kind == .request {
                number += 1
                cycles.append(
                    TimelineCycle(id: event.id, number: number, events: [event], completion: event.completion))
            } else {
                if cycles.isEmpty { cycles.append(TimelineCycle(id: id + "-opening", number: nil, events: [])) }
                cycles[cycles.count - 1].events.append(event)
            }
        }
        return cycles.compactMap { cycle in
            var visible = cycle
            visible.events = cycle.events.filter { showContext || $0.kind != .context }
            return visible.events.isEmpty ? nil : visible
        }
    }
}

/// Scheduler measurements for a request, and its comparison with a preceding request.
public struct RequestMetrics: Sendable, Equatable {
    public var model: String?
    /// The event ID of the request this one was compared with.
    public var previousRequest: String?
    /// Request fields whose values differ from the previous request.
    public var changedFields: [String] = []
    public var comparisonInferred = false
    /// `true` when the comparison candidate shares history but is not an exact prefix:
    /// a possible rewrite, compaction, or instruction change.
    public var possibleReset = false
    /// Prompt tokens reported by the scheduler at admission.
    public var promptTokens: Int?
    /// Tokens reported by the scheduler at finish.
    public var generatedTokens: Int?
    /// Timestamp of the scheduler admission record.
    public var schedulerStart: String?
    /// Seconds from scheduler admission to scheduler finish.
    public var elapsedSeconds: Double?
}

// MARK: - Filtering

/// Timeline filter categories. Raw values are user-facing labels and persisted preferences.
public enum EventFilter: String, Sendable, CaseIterable {
    case all = "All events"
    case requests = "Requests"
    case tools = "Tools & results"
    case output = "Model output"
    case issues = "Errors & warnings"
    case messages = "Messages"

    public func includes(_ event: InspectorEvent) -> Bool {
        switch self {
        case .all: true
        case .requests: event.kind == .request
        case .tools: event.kind == .call || event.kind == .result
        case .output: event.kind == .output
        case .issues: event.isIssue
        case .messages: event.kind == .user || event.kind == .context
        }
    }
}
